function viewLanding(){const f=facultyName(state.selectedFaculty);return `<section class="landing profile-landing"><header>${brand()}<button class="btn ghost sm" data-action="change-faculty">← Cambiar facultad</button></header><main class="role-choice"><span class="eyebrow">PASO 02 DE 02 · MODALIDAD DE REGISTRO</span><h1>Diagnóstico de puestos<br><em>y funciones</em></h1><div class="faculty-selected"><span>FACULTAD SELECCIONADA</span><strong>FACULTAD DE ${esc(U(f))}</strong></div><h2>¿Qué información desea registrar?</h2><p class="muted">Ingrese directamente y complete el formulario correspondiente. Todos los perfiles de facultad ingresan directamente, sin claves ni cuentas individuales. La consulta y validación de expedientes ajenos requiere una sesión supervisada de la URH.</p><div class="rolelist"><button class="rolecard" data-role="staff"><span class="roleicon">▤</span><span class="roletext"><b>Personal administrativo</b><small>Funciones, actividades, productos, frecuencia y condiciones de trabajo</small></span><span class="arw">→</span></button><button class="rolecard" data-role="faculty_admin"><span class="roleicon">✓</span><span class="roletext"><b>Administrador de facultad</b><small>Registra sus funciones sin clave; la revisión de fichas ajenas se realiza con supervisión URH</small></span><span class="arw">→</span></button><button class="rolecard" data-role="authority"><span class="roleicon">⌂</span><span class="roletext"><b>Decanos y directores</b><small>Necesidades no atendidas, servicios externos y oportunidades de mejora</small></span><span class="arw">→</span></button></div><div class="role-disclaimer">La revisión de fichas ajenas se realiza con autorización de la URH. Sin ella, la recepción es directa pero ninguna persona queda acreditada como validadora.</div></main></section>${ribbon()}`;}
function viewAuth(){return `<section class="landing auth-landing"><header>${brand()}<button class="btn ghost sm" data-action="go-home">← Volver</button></header><main class="auth"><div class="auth-head"><span class="eyebrow">ACCESO URH</span><h2>Administración institucional</h2><p class="muted">Ingrese con su cuenta autorizada de la Unidad de Recursos Humanos.</p></div><div class="card"><div class="callout bluecall"><b>UNIDAD DE RECURSOS HUMANOS</b><br>Administración de registros e indicadores de las facultades.</div><div class="spacer"></div><form id="loginForm" class="stack"><div class="field"><label>Correo institucional</label><input type="email" name="email" placeholder="usuario@unitru.edu.pe" value="${esc(state.authEmail)}" required autocomplete="username"></div><div class="field"><label>Contraseña</label><input type="password" name="password" placeholder="Ingrese su contraseña" required autocomplete="current-password" minlength="8"></div><button class="btn primary wide" type="submit">Ingresar al panel URH →</button></form><p class="tiny muted" style="margin-top:18px">Las credenciales se verifican en Supabase Auth y no se almacenan en GitHub.</p></div></main></section>`;}
