function viewAwaiting(){return `<section class="landing auth-landing"><header>${brand()}<button class="btn ghost sm" data-action="logout">Cerrar sesión</button></header><main class="auth"><div class="auth-head"><span class="eyebrow">VERIFICACIÓN DE PERFIL</span><h2>Solicitud de acceso registrada</h2><p class="muted">Su identificación fue guardada y el perfil solicitado necesita autorización institucional.</p></div><div class="card"><div class="callout bluecall"><b>Perfil solicitado:</b> ${esc(roles[state.profile?.requested_role]?.label||'PERFIL DE USUARIO')}<br><b>Facultad:</b> ${esc(facultyName(state.profile?.faculty_id))}</div><p class="subtle" style="margin-top:20px">La Dirección General de Administración y la Unidad de Recursos Humanos deben verificar la habilitación del rol antes de permitir el acceso al módulo de validación o al diagnóstico de autoridades. Ingrese nuevamente después de recibir la confirmación.</p><button class="btn primary" data-action="logout">Volver al inicio</button></div></main></section>`;}
function shell(inner,title='Registro funcional'){const menus=navItems();return `<div class="shell ${state.sidebarHidden?'sidebar-collapsed':''}"><aside class="sidebar" id="sidebar" aria-label="Navegación de la aplicación">${brand()}<div class="sidebar-heading">NAVEGACIÓN</div><nav class="sidebar-nav">${menus.map(([key,icon,name])=>`<button class="side-item ${state.nav===key?'active':''}" data-nav="${key}">${barIcon(icon)}<span>${name}</span></button>`).join('')}</nav><div class="side-bottom"><div class="person">${esc(state.profile?.first_names||'USUARIO')} ${esc(state.profile?.last_names||'')}</div><div class="micro">${esc(roles[state.role]?.label||'')}</div><button data-action="logout">↗ ${state.role==='urh_admin'?'Cerrar sesión':'Volver al inicio'}</button></div></aside><button type="button" class="sidebar-scrim" data-action="close-menu" aria-label="Cerrar menú de navegación" tabindex="-1"></button><div class="content"><header class="topbar"><div class="flex"><button class="btn ghost sm toolbar-mob" type="button" data-action="menu" aria-controls="sidebar" aria-expanded="${state.sidebarHidden?'false':'true'}" aria-label="Mostrar u ocultar el menú de navegación" title="Mostrar u ocultar el menú">☰ <span class="menu-caption">${state.sidebarHidden?'Mostrar menú':'Ocultar menú'}</span></button><button class="back-nav" type="button" data-action="go-back" aria-label="Regresar a la pantalla anterior"><span aria-hidden="true">←</span> Regresar</button><div class="breadcrumb">Diagnóstico de puestos / <b>${esc(title)}</b></div></div><div class="topright"><span class="pill">${esc(state.role==='urh_admin'?'COBERTURA INSTITUCIONAL':facultyName(state.profile?.faculty_id))}</span><span class="avatar">${esc((state.profile?.first_names||'U').slice(0,1))}</span></div></header><main class="main">${inner}<div class="footer-note">Dirección General de Administración · Unidad de Recursos Humanos · Universidad Nacional de Trujillo · Uso institucional. El diagnóstico no constituye, por sí solo, una evaluación individual de desempeño.</div></main></div></div>${ribbon()}${state.modal?modal():''}`;}
function pageTitle(kicker,title,desc,action=''){return `<div class="page-intro"><div><span class="eyebrow">${kicker}</span><h2>${title}</h2><p>${desc}</p></div>${action}</div>`;}
function input(name,label,value='',type='text',opts={}){const full=opts.full?' full':'';const hint=opts.hint?`<span class="hint">${esc(opts.hint)}</span>`:'';const check=/^prod_\d+_\d+_\d+_name$/.test(name)?`<div class="writing-check" data-writing-check="${esc(name)}" role="status" hidden></div>`:''; const required=opts.required?'required':'';const upp=opts.upper!==false&&type!=='email'?'upper':'';return `<div class="field${full}"><label for="${name}">${esc(label)}${required?' *':''}</label><input id="${name}" name="${name}" type="${type}" class="${upp}" value="${esc(value)}" ${required} ${opts.maxlength?`maxlength="${opts.maxlength}"`:''} ${opts.placeholder?`placeholder="${esc(opts.placeholder)}"`:''}/>${check}${hint}</div>`;}
function select(name,label,options,chosen='',opts={}){return `<div class="field ${opts.full?'full':''}"><label for="${name}">${esc(label)}${opts.required?' *':''}</label><select id="${name}" name="${name}" ${opts.required?'required':''}><option value="">Seleccione una opción</option>${options.map(x=>{const value=typeof x==='string'?x:x.value,label=typeof x==='string'?x:x.label;return `<option value="${esc(value)}" ${value===chosen?'selected':''}>${esc(label)}</option>`}).join('')}</select>${opts.hint?`<span class="hint">${esc(opts.hint)}</span>`:''}</div>`;}
function textarea(name,label,value='',opts={}){const check=/^(fn_desc_\d+|act_\d+_\d+)$/.test(name)?`<div class="writing-check" data-writing-check="${esc(name)}" role="status" hidden></div>`:'';return `<div class="field full"><label for="${name}">${esc(label)}${opts.required?' *':''}</label><textarea id="${name}" name="${name}" rows="${opts.rows||3}" ${opts.required?'required':''} placeholder="${esc(opts.placeholder||'')}" class="${opts.upper===false?'':'upper'}">${esc(value)}</textarea>${check}${opts.hint?`<span class="hint">${esc(opts.hint)}</span>`:''}</div>`;}
function profileView(){let p=state.profile||emptyProfile(state.role);return `<div class="card"><div class="section-head"><span class="section-mark">01</span><div><h3>Identificación personal y académica</h3><p class="muted tiny" style="margin:0">Consigne información vigente. Los nombres, apellidos y direcciones se registran en mayúsculas.</p></div></div><form id="profileForm"><div class="input-grid">${input('last_names','APELLIDOS',p.last_names,'text',{required:true})}${input('first_names','NOMBRES',p.first_names,'text',{required:true})}${input('dni','NÚMERO DE DOCUMENTO NACIONAL DE IDENTIDAD (DNI)',p.dni,'text',{required:true,maxlength:8,hint:'Ocho dígitos numéricos.'})}${input('worker_code','CÓDIGO DE TRABAJADOR',p.worker_code,'text',{required:true})}${input('job_title','DENOMINACIÓN DEL PUESTO QUE OCUPA',p.job_title||'','text',{required:true})}${input('address','DOMICILIO ACTUAL',p.address,'text',{required:true,full:true})}${input('phone','NÚMERO DE CELULAR',p.phone,'tel',{required:true,hint:'Ingrese su número de celular vigente (nueve dígitos).'})}${input('institutional_email','CORREO INSTITUCIONAL (UNITRU)',p.institutional_email,'email',{required:true,upper:false})}${input('personal_email','CORREO ELECTRÓNICO PERSONAL',p.personal_email,'email',{required:true,upper:false})}${academicView(p)}<div class="field"><label>FACULTAD DE ADSCRIPCIÓN *</label><input readonly value="FACULTAD DE ${esc(U(facultyName(p.faculty_id||state.selectedFaculty)))}" aria-label="Facultad seleccionada"><input name="faculty_id" type="hidden" value="${esc(p.faculty_id||state.selectedFaculty)}"></div>${(state.role==='authority'||prefStore.get('unt.requested_role')==='authority')?`${select('authority_scope','RESPONSABILIDAD ACADÉMICA O DE GOBIERNO',[{value:'DECANATO',label:'DECANO(A)'},{value:'ESCUELA',label:'DIRECTOR(A) DE ESCUELA PROFESIONAL'},{value:'DEPARTAMENTO',label:'DIRECTOR(A) DE DEPARTAMENTO ACADÉMICO'}],p.authority_scope||'',{required:true})}${input('authority_unit','ESCUELA PROFESIONAL O DEPARTAMENTO ACADÉMICO (SEGÚN CORRESPONDA)',p.authority_unit||'','text',{full:true,placeholder:'EJ. ESCUELA PROFESIONAL DE ECONOMÍA; NO CORRESPONDE SI ES DECANO'})}`:''}${input('org_unit','UNIDAD DE ORGANIZACIÓN DONDE DESEMPEÑA SUS LABORES',p.org_unit,'text',{required:true,full:true,placeholder:'EJ. SECRETARÍA ACADÉMICA, DECANATO, DIRECCIÓN DE ESCUELA...'})}</div><div class="divider"></div><div class="form-actions right"><button class="btn primary" type="submit">Continuar →</button></div></form></div>`;}
function normalizedAcademicProfile(p){const level=String(p.education_level||'').toUpperCase();const result={...p,education_level:['SECUNDARIA','TÉCNICO','SUPERIOR'].includes(level)?level:level.startsWith('SECUNDARIA')?'SECUNDARIA':level.includes('TÉCNIC')?'TÉCNICO':level?'SUPERIOR':(p.role==='authority'?'SUPERIOR':'')};let titles=Array.isArray(p.academic_titles)?p.academic_titles:[];let grades=Array.isArray(p.academic_grades)?p.academic_grades:[];if(!titles.length&&p.professional_title){titles=[{type:result.education_level==='TÉCNICO'?'TÉCNICO':'PROFESIONAL',name:p.professional_title}];}if(!grades.length){if(level==='BACHILLER')grades.push({level:'BACHILLER',name:p.higher_detail||''});const nM=Math.max(0,Number(p.masters_count)||0),nD=Math.max(0,Number(p.doctorates_count)||0);String(p.masters_detail||'').split('\n').slice(0,nM).forEach(name=>grades.push({level:'MAESTRÍA',name}));String(p.doctorates_detail||'').split('\n').slice(0,nD).forEach(name=>grades.push({level:'DOCTORADO',name}));}result.academic_titles=titles;result.academic_grades=grades;return result;}
function academicView(profile){const p=normalizedAcademicProfile(profile),level=p.education_level;const isHigher=level==='SUPERIOR',isTech=level==='TÉCNICO';return `<div class="academic-level-wrap full"><div class="field"><label id="education_title">NIVEL EDUCATIVO *</label><div class="education-pills" role="radiogroup" aria-labelledby="education_title">${[['SECUNDARIA','Secundaria'],['TÉCNICO','Técnico'],['SUPERIOR','Superior']].map(([code,label])=>`<label class="education-choice ${level===code?'selected':''}"><input type="radio" name="education_level" value="${code}" ${level===code?'checked':''} required><span>${label}</span></label>`).join('')}</div><span class="hint">Marque únicamente el nivel educativo alcanzado. Los grados y títulos se registran aparte, si corresponde.</span></div></div><div id="academic_extra" class="academic-extra full ${isTech||isHigher?'':'is-hidden'}">${input('higher_detail',isTech?'ESPECIALIDAD O PROGRAMA DE FORMACIÓN TÉCNICA':'CARRERA, PROGRAMA O ESPECIALIDAD DE ESTUDIOS SUPERIORES',p.higher_detail||'','text',{full:true,placeholder:'INDIQUE LA DENOMINACIÓN SI CORRESPONDE'})}<div class="academic-block"><div class="academic-block-head"><div><b>${isTech?'Títulos técnicos obtenidos':'Títulos obtenidos'}</b><p>Registre cada título que efectivamente posee. Si no tiene ninguno, puede dejar este apartado vacío.</p></div><button type="button" class="btn ghost sm" data-action="add-academic-title">+ Añadir título</button></div><div class="academic-list">${p.academic_titles.map((row,i)=>`<div class="academic-line"><div class="field"><label for="academic_title_${i}">TÍTULO ${i+1} · DENOMINACIÓN</label><input id="academic_title_${i}" class="upper" name="academic_title_${i}" value="${esc(row.name||'')}" placeholder="EJ. ${isTech?'TÉCNICO EN CONTABILIDAD':'CONTADOR PÚBLICO, ECONOMISTA, INGENIERO...'}" required></div><button class="btn ghost sm remove-academic" type="button" data-action="delete-academic-title" data-idx="${i}" aria-label="Eliminar título ${i+1}">Eliminar</button></div>`).join('')||'<p class="academic-empty">Sin títulos registrados.</p>'}</div></div>${isHigher?`<div class="academic-block"><div class="academic-block-head"><div><b>Grados académicos obtenidos</b><p>Agregue los grados que posee: bachiller, maestría o doctorado. Puede incorporar más de uno.</p></div><button type="button" class="btn ghost sm" data-action="add-academic-grade">+ Añadir grado</button></div><div class="academic-list">${p.academic_grades.map((row,i)=>`<div class="academic-line"><div class="field"><label for="academic_grade_${i}_level">GRADO ${i+1}</label><select id="academic_grade_${i}_level" name="academic_grade_${i}_level" required><option value="">Seleccione un grado</option>${['BACHILLER','MAESTRÍA','DOCTORADO'].map(x=>`<option value="${x}" ${row.level===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="academic_grade_${i}_name">DENOMINACIÓN DEL GRADO ${i+1}</label><input id="academic_grade_${i}_name" name="academic_grade_${i}_name" class="upper" value="${esc(row.name||'')}" placeholder="EJ. MAGÍSTER EN GESTIÓN PÚBLICA" required></div><button class="btn ghost sm remove-academic" type="button" data-action="delete-academic-grade" data-idx="${i}" aria-label="Eliminar grado ${i+1}">Eliminar</button></div>`).join('')||'<p class="academic-empty">Sin grados académicos registrados.</p>'}</div></div>`:''}</div>`;}
function updateAcademicVisibility(){const form=$('#profileForm');if(!form)return;state.profile={...(state.profile||{}),...formProfile()};state.profile=normalizedAcademicProfile(state.profile);if(state.profile.education_level==='SECUNDARIA'){state.profile.academic_titles=[];state.profile.academic_grades=[];state.profile.higher_detail='';}if(state.profile.education_level==='TÉCNICO'){state.profile.academic_grades=[];}render(true);}
